insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 1, 'On the 8.000000 ft drum a level fraction of 0.300000 stands 2.400000 ft deep and holds 12.682775 ft2 of the 50.265482 ft2 cross-section. Why is the liquid area well under three tenths of the circle?', '["The figure quoted is what the liquid may occupy after a vapour allowance has been taken off the top of the segment, which is why it falls short of three tenths of 50.265482 ft2.", "The level fraction was applied to the liquid depth of 2.400000 ft rather than to the diameter.", "The bottom of a circle is narrow, so a step in level buys far more area near the centreline than it buys near the invert.", "The engine bisects towards the depth and stops after 100 steps, so the area it prints is a converged approximation that lands a little under the exact three tenths of the shell."]'::jsonb, 2, 'Depth is linear in the level fraction and area is not. The same drum at 0.750000 holds 40.438525 ft2, well over three quarters, because by then the widest part of the circle is covered.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 2, 'Which quantity on a cross-section row moves in a straight line with the level fraction on the 8.000000 ft drum?', '["The liquid depth: a level of 0.300000 gives 2.400000 ft and a level of 0.750000 gives 6.000000 ft, each one the level fraction times the diameter.", "The liquid area, which is why 12.682775 ft2 can be carried up to 40.438525 ft2 by scaling the level fraction between the two rows, a segment being the share of the circle a level buys.", "The gas-liquid chord, which climbs from 7.332121 ft at a level of 0.300000 to 8.000000 ft at a level of 0.500000 in even steps with the level.", "The gas area, because the gas keeps whatever the liquid leaves behind and the total of 50.265482 ft2 never moves off any row of the table."]'::jsonb, 0, 'Depth is the level fraction times the diameter, so 0.300000 of 8.000000 ft is 2.400000 ft. The areas bend, and the chord turns round at half full and falls away again.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 3, 'An area of 15.678751 ft2 is handed back to the 8.000000 ft drum to recover the depth that produced it. What does the engine do with that request?', '["It inverts the segment formula in closed form and returns 2.800000 ft, which is exact because no iteration is involved anywhere in that step.", "It interpolates between the six tabulated levels the drum is published at and returns the depth nearest 2.800000 ft, which is why the table carries those six rows.", "It refuses, because an area is an output of the cut and a circular segment takes a depth or a level fraction as its input rather than an area.", "It bisects 100 times and returns 2.800000 ft, so the two directions agree."]'::jsonb, 3, 'The bisection resolves the depth to double precision. On the 10.000000 ft drum 49.202836 ft2 gives back 6.000000 ft in the same way.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 4, 'A segment area larger than the whole circle comes back as { error: "the area must lie between zero and the full circle" }, while a liquid level of 0 throws a SeparatorInputError. What separates those two answers?', '["The throw carries no `input` property while the returned error names the field that failed, so only the returned form can be shown beside the box on a studio form.", "A throw says the request was malformed, and a returned error says the request was well formed and the method has no answer for it.", "The throw is reserved for anything the studio form can validate for itself, and the returned error for states only the geometry can discover once the cut has been attempted.", "One is raised while the inputs are read and the other once the vessel has been sized."]'::jsonb, 1, 'A SeparatorInputError carries an `input` property naming the input, and no default or clamp stands in for it. The area message describes a state: the inputs were readable and the geometry is impossible.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 5, 'A sizing sheet arrives with liquidLevelFrac set to 1 and the engine answers "liquidLevelFrac must lie strictly between 0 and 1 (got 1)". What should a reader do with that answer?', '["Treat it as a statement about the input rather than about the drum: a full vessel has no gas space for anything to separate in, and the usual cause is a percentage typed where a fraction belongs.", "Catch the refusal and size the drum at 0.500000, the level the six teaching rows are centred on.", "Read it as a verdict on the vessel, which at 8.000000 ft is too small to be run that full.", "Round the level down to 0.750000, the highest level this drum is published at."]'::jsonb, 0, 'The word strictly is doing the work. A caught throw that carries on at 0.500000 has turned a refusal into an assumption, and the engine has no honest dimension for a full drum.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 6, 'Levels of 0.400000 and 0.600000 on the same drum both report a gas-liquid chord of 7.838367 ft. What does a chord on its own therefore fail to say about the operating state?', '["Whether the drum is being sized or checked, since the engine writes a chord only for a level it was handed and leaves the field empty for a level it derived itself.", "Which of the two duties of the gas space it belongs to, since the same width serves as the flow area and as the distance a droplet falls.", "Whether the vessel is running high or low, because a chord the same distance above the centreline is as wide as one the same distance below it.", "Whether the level sits inside the range the engine accepts at all."]'::jsonb, 2, 'The chord rises to the diameter at half full and falls away on both sides of it, so 7.838367 ft belongs to two levels. The level fraction is what tells the two apart.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 7, 'Old work passed the gas-liquid chord into a check on the water layer in a three-phase vessel. Why was that error so hard to see?', '["The chord and the water layer agree at a level of 0.500000, so the fault only showed itself once an operator moved the level controller off the centreline.", "The chord is a width across the drum and a layer is a height, so the check was reading a layer that was not there while every figure on the page was still in feet.", "The check was advisory and printed no verdict of its own, so nothing downstream of it ever moved and no reviewer had a number to disagree with.", "The chord was carried in metres while the layer was carried in feet, so the two disagreed by a factor any reviewer would read as an ordinary unit slip."]'::jsonb, 1, 'A number in feet that came out of the wrong geometry is the hardest sort of error to find. The chord is the width of the gas-liquid surface and an interface sits at its own height inside the liquid.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 8, 'Why would a spot check run at a level of 0.500000 never expose a chord used in the place of the diameter?', '["Because the engine substitutes the diameter for the chord at half full, where the segment relation would otherwise be taken across the widest part of the circle.", "Because a check at half full compares areas rather than widths, and the liquid and the gas both hold 25.132741 ft2 there whichever width was used to reach them.", "Because the chord at 0.500000 is 7.838367 ft and the gap from the diameter is inside the tolerance a spot check applies to any vessel figure.", "At half full the chord is 8.000000 ft, which is the diameter, so the two agree on that one row."]'::jsonb, 3, 'At a level of 0.300000 the chord is 7.332121 ft against a diameter of 8.000000 ft and the slip shows. Half full is the one level where the two are the same number.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 9, 'The published 6.000000 ft segment at a level of 0.750000 holds 22.746670 ft2 and the published 10.000000 ft segment at 0.300000 holds 19.816836 ft2. What does that pair establish?', '["The segment routine loses accuracy on the larger bore, which is why the 12.000000 ft case at half full is published at 56.548668 ft2 as a check against it.", "Liquid area scales with the bore and with the level in the same proportion, so the two published cases were chosen to land within a few ft2 of one another.", "A smaller drum run high holds more liquid than a larger drum run low, so a diameter on its own does not rank two vessels by liquid area.", "A level above 0.500000 sits outside the range the engine will size at."]'::jsonb, 2, '22.746670 ft2 on a 6.000000 ft drum beats 19.816836 ft2 on a 10.000000 ft drum. The level decides how much of the circle the liquid is given.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 10, 'At a level of 0.300000 the 8.000000 ft drum gives the gas 37.582708 ft2 and 5.600000 ft. Which duty does each of those two numbers serve?', '["The area sets the velocity the gas travels at along the drum, and the height is the distance an entrained droplet has to fall before it reaches the liquid surface.", "The area sets the distance a droplet falls and the height sets the velocity, since gas rises through the vessel towards the outlet.", "Both of them serve the velocity: the area divides the rate and the height corrects that result for the shape of the segment.", "The area serves the capacity verdict and the height serves the slenderness the finished vessel is judged on."]'::jsonb, 0, 'Velocity is the actual rate over the gas area, 0.784681 ft/s on that row. The fall is across the gas height of 5.600000 ft, which is the diameter less the liquid depth.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 11, 'Two velocity errors are available in the gas space: dividing by the full 50.265482 ft2, and dividing the standard rate of 1273.148148 standard ft3/s by the gas area. Which one does more damage?', '["The standard rate, because 1273.148148 standard ft3/s is what the drum actually passes once the pressure of 614.700000 psia and a z of 0.908065 have been applied to the stream.", "The full cross-section, because at half full it halves the velocity and gives a plausible figure saying the vessel has twice the room it has.", "Neither, because the capacity verdict is taken against the settling velocity of 1.958255 ft/s.", "The standard rate, because a velocity tens of times too high still lands inside the band a reviewer expects to see on a drum of 8.000000 ft."]'::jsonb, 1, 'The absurd answer is usually caught and the halved one is not, and it errs in the comfortable direction. The drum passes 29.490437 ft3/s through 25.132741 ft2 at 1.173387 ft/s.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 12, 'What exactly does a level of 0.500000 buy on the 8.000000 ft drum?', '["The largest liquid area the drum can offer, which is why a retention volume is worked at half full before any other level is put to it.", "A liquid area of 25.132741 ft2 that a level controller cannot drift away from without raising an alarm, which is what makes half full the design level.", "The level at which the liquid and the gas ask for the same length, so the vessel is balanced between the two duties it has to serve.", "Equal areas of 25.132741 ft2 and a chord equal to the diameter."]'::jsonb, 3, 'At 0.750000 the liquid holds 40.438525 ft2, so half full is not the largest area available. What belongs to it is the symmetry of the areas and the chord of 8.000000 ft.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 13, 'A drum sized at a level of 0.500000 for 23.270539 ft of length is then run at 0.300000. What has changed?', '["Nothing measurable, because 23.270539 ft is a property of the vessel itself.", "The retention volume of 584.852431 ft3, which falls away with the level so that the length the drum was bought at still covers the duty.", "The same duty now asks for 46.113917 ft in a vessel that was bought at 23.270539 ft, and no steel moved to bring that about.", "The gas side, which is now worse off because a lower level leaves the gas 37.582708 ft2 to cross rather than 25.132741 ft2."]'::jsonb, 2, 'The liquid area fell from 25.132741 ft2 to 12.682775 ft2, so the same retention volume has to lie in a narrower trough. A length is meaningless without the level it was sized at.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 14, 'Every row of the cross-section table reports a total area of 50.265482 ft2 while the liquid area runs from 7.156723 ft2 up to 40.438525 ft2. What is that column for?', '["It records the area the engine held before the vapour allowance above the liquid was taken off the top of the segment on each row.", "It fixes the shell: the level splits one circle into two shares and never changes how much circle there is.", "It is the area the gas flows through on every row, the liquid lying in the bottom of the circle without taking any of the cross-section away from the gas.", "It is the area the two length requirements are divided into, which is what allows a liquid length and a gas length to be added on one row."]'::jsonb, 1, 'A liquid area of 7.156723 ft2 at a level of 0.200000 and 40.438525 ft2 at 0.750000 are two shares of the same 50.265482 ft2 of shell.'),
  ('separation', 'intermediate', 'module', 'm01-the-horizontal-vessel', 15, 'Dropping the level from 0.500000 to 0.300000 takes the liquid requirement from 23.270539 ft to 46.113917 ft while the gas velocity falls from 1.173387 ft/s to 0.784681 ft/s. Why do the two sides move in opposite directions?', '["One cut divides the circle between them, so the liquid loses the area it needs for its volume in the same step that the gas gains the area it needs to slow down.", "The gas velocity is taken across the chord rather than across the gas area, and a chord narrows as the level falls while the liquid area narrows with it.", "The retention volume rises as the gas area rises, so the liquid requirement grows for the same reason that the velocity falls away.", "The settling velocity of 1.958255 ft/s climbs as the level drops, which slows the gas and lengthens the liquid in one move."]'::jsonb, 0, 'The liquid area fell to 12.682775 ft2 while the gas area rose to 37.582708 ft2 out of the same 50.265482 ft2. The drum got worse at holding liquid and better at carrying gas.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 1, 'The liquid requirement on the 8.000000 ft drum divides 584.852431 ft3 by 25.132741 ft2 at a level of 0.500000. What does dividing by the full 50.265482 ft2 instead do to the answer?', '["It leaves the requirement where it stands, because the retention volume of 584.852431 ft3 is itself built from the cross-section and the two slips cancel on every row.", "It halves the requirement at half full, and the slip grows as the level falls, since at 0.300000 the liquid holds 12.682775 ft2 of that circle.", "It doubles the requirement to 46.113917 ft, which is the figure a level of 0.300000 gives, so the slip cannot be told apart from a level that was typed wrongly.", "It moves no length at all and shifts only the slenderness."]'::jsonb, 1, '584.852431 ft3 over 25.132741 ft2 is 23.270539 ft. The denominator is the area the level cut out, and at a level of 0.300000 the same slip is worth a factor of four.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 2, 'The retention volume of 584.852431 ft3 is a liquid rate held for a retention time. What happens to all six liquid lengths in the family if that retention time is doubled?', '["Every liquid length doubles and every gas length halves, because the drum keeps its cross-section of 50.265482 ft2 while the liquid takes a larger share of it.", "Only the rows the liquid controls move, and on this family that is the 5.000000 ft row on its own.", "Nothing moves until the level is raised, since retention is held in the liquid area.", "Every liquid length doubles, because the volume doubles while each row divides it by an area that has not moved."]'::jsonb, 3, 'The liquid requirement is the retention volume over the liquid area, so 23.270539 ft becomes twice that on the 8.000000 ft drum. A retention time is a specification somebody chose.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 3, 'Across the family the liquid requirement falls from 59.572579 ft at a bore of 5.000000 ft to 14.893145 ft at 10.000000 ft. Why is the fall so steep?', '["The liquid area rises with the square of the diameter while the retention volume of 584.852431 ft3 stays where it is, so a drum of twice the bore needs roughly a quarter of the length.", "The level is raised on the wider drums, which hands the liquid a larger share of a larger circle on every row of the table.", "The retention volume falls away as the bore widens, because a wider drum holds the same liquid for longer.", "The gas takes less of the circle on a wide drum and the liquid length follows the gas area down."]'::jsonb, 0, 'At a bore of 5.000000 ft the liquid has 9.817477 ft2 and at 10.000000 ft it has 39.269908 ft2. Two extra feet on the narrow drum is worth almost thirty feet of length.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 4, 'The gas requirement moves only from 3.834882 ft to 1.917441 ft across a doubling of the bore. What holds it inside such a narrow range?', '["The gas length is held at the gas height by the capacity rule on every row, so it can follow the bore and never the duty it was given.", "The settling velocity of 1.958255 ft/s is recomputed for each bore, and its rise with the diameter cancels most of the fall in the gas velocity.", "Widening the drum raises the gas height and lowers the gas velocity at the same time, and the two work against each other.", "The actual gas rate of 29.490437 ft3/s is shared out between the rows of the sweep, so no single row carries the whole stream."]'::jsonb, 2, 'The gas length is the gas height times the ratio of the gas velocity to the settling velocity. A wider drum lengthens the fall and slows the gas inside one product.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 5, 'On the 8.000000 ft drum the liquid asks for 23.270539 ft and the gas asks for 2.396801 ft, and the engine reports the controlling requirement as liquid. What does that label assert?', '["That the vessel has passed its gas check, since a requirement can only take control of a vessel whose other requirement the dimensions have already satisfied.", "That the gas requirement of 2.396801 ft has been absorbed into the liquid requirement and no longer needs reporting on its own.", "That the drum was sized for a liquid duty and its gas load was never read at all.", "Only that the liquid number was the larger of the two, so the vessel is 23.270539 ft long."]'::jsonb, 3, 'Controlling says which of two numbers was larger. The 5.000000 ft and 6.000000 ft rows are liquid controlled and fail on gas capacity, at margins of 0.651911 and 0.938751.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 6, 'The published 6.000000 ft case needs 20.684923 ft for its liquid and the published 8.000000 ft case at a level of 0.400000 needs 31.149488 ft. Why is the wider vessel the longer one?', '["Its gas requirement of 4.157188 ft has taken control of the length, and a gas controlled vessel always runs longer than its liquid alone would ask for.", "It runs at a lower level with a larger duty and a longer hold, 30000.000000 bpd on 5.000000 minutes against 25000.000000 bpd on 3.000000 minutes.", "Its slenderness of 3.893686 sits higher in the band, and a higher slenderness is a longer drum at any bore.", "Liquid area falls as the bore widens, so the 8.000000 ft drum holds less than the 6.000000 ft drum."]'::jsonb, 1, 'Both published cases are controlled by the liquid, at 20.684923 ft and 31.149488 ft. A level of 0.400000 gives the liquid less of the circle while the duty and the hold are both larger.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 7, 'The gas length uses the Souders-Brown velocity at the horizontal K as its droplet settling velocity. What may a reader conclude from the 2.396801 ft it produces?', '["That it is a published result out of API 12J, which is why the module quotes it to six decimals beside the liquid requirement.", "That it is the droplet size the vessel was sized for, carried into a length by the capacity rule.", "That it is the engine''s own answer with its provenance unverified, because that packaging has not been checked against API 12J or against Arnold and Stewart, so no design case may rest on it.", "That it is a lower bound, since a stated droplet diameter would always ask for less length."]'::jsonb, 2, 'It is HELD FOR LITERATURE. If the published method sizes a gas length from a stated droplet diameter, the gas length and every conclusion resting on it change.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 8, 'What happens if the gas requirement of 2.396801 ft is written down as the vessel length on ABANA-2?', '["A drum is specified at 2.396801 ft against a real requirement of 23.270539 ft.", "The drum comes out short on gas and adequate on liquid, since the liquid requirement is met by any length that clears the gas height of 4.000000 ft.", "The slenderness drops out of the band of 3.000000 to 5.000000, which is the check that catches the slip before the sheet leaves the desk.", "Nothing at all, because the engine reports the larger of the two requirements as the length whichever figure was copied across."]'::jsonb, 0, 'It is the most expensive single error available in horizontal sizing. The gas requirement is one of two candidates and it is usually the smaller of them.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 9, 'The 8.000000 ft drum reads a slenderness of 2.908817 against a band of 3.000000 to 5.000000 and carries the reason ld-out-of-band. What has it failed?', '["A physical limit on a horizontal drum, below which the liquid surface is too short for the retention volume of 584.852431 ft3 to settle across.", "A preference about fabrication and layout that somebody typed, while its margin of 1.668891 says it carries its gas.", "The capacity check, since a slenderness under the lower bound leaves the gas space too short for a droplet to land inside it.", "Nothing at all, because a band is advisory and the row carries no reason with it."]'::jsonb, 1, 'A band is an input about nozzle spacing, supports, transport and the cost of heads against shell. The row holds its liquid in 23.270539 ft and carries its gas.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 10, 'Widening the band from 3.000000 to 5.000000 out to 3.000000 to 7.000000 brings the 6.000000 ft row inside it at 6.894974. What does that row become?', '["A feasible row, because a slenderness inside the band is what a sweep tests before it reports whether a vessel can carry the gas it was given.", "A row the sweep drops, since a change of band invalidates the dimensions computed under the old bounds.", "The shortest drum in the family, at 41.369847 ft.", "A row inside the band that still cannot carry its gas, so membership and feasibility stay separate readings."]'::jsonb, 3, 'The 6.000000 ft row reports a margin of 0.938751 and gasCapacityOk false whatever the band says. Membership is a preference and feasibility is a verdict.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 11, 'Which of the six ABANA-2 rows sits inside a band of 3.000000 to 5.000000, and what do the others report?', '["Only the 7.000000 ft row at 4.342025, with the narrow drums too long for their bore at 11.914516 and 6.894974 and the wide ones too short at 2.042955 and 1.489314.", "The 7.000000 ft and the 8.000000 ft rows, at 4.342025 and 2.908817, with the remaining four outside the bounds on one side or the other.", "Every row above 7.000000 ft, because slenderness climbs with the bore on a fixed duty.", "None of them, which is why the sweep reports the band as an input."]'::jsonb, 0, 'The 8.000000 ft row reads 2.908817 and misses the lower bound by a small amount. One row of six is inside that band.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 12, 'Which inputs does the liquid length requirement read?', '["A retention volume, a liquid area and the settling velocity, since the liquid has to be given time to release the gas it carries into the space above it.", "A retention volume, a liquid area and the gas velocity, which is what fixes how much of the drum the liquid is allowed to occupy.", "A retention volume and a liquid area, and nothing about the gas, the pressure or the mist extractor.", "A liquid rate, a retention time and the slenderness band the finished vessel is judged against."]'::jsonb, 2, 'It is one division: 584.852431 ft3 over 25.132741 ft2 gives 23.270539 ft. The gas side of the sheet does not enter it.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 13, 'The published gas-overloaded case reports a gas length of 16.976527 ft against a gas height of 3.000000 ft and names gas as the controlling requirement. What does that tell a reviewer?', '["That the vessel is holding more liquid than its bore allows, so the gas requirement rose to cover the surface the retention volume needed.", "That the vessel has already failed its capacity check, at a margin of 0.176715 with gasCapacityOk false.", "That a droplet in that vessel lands well inside the gas space, which is why the requirement can exceed the gas height at all.", "That the case was run at a level too low for the gas to be given a height."]'::jsonb, 1, 'The gas moves at 2.829421 ft/s against a settling velocity of 0.500000 ft/s, so a droplet rides more than five times the height of the gas space before it lands.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 14, 'On the 8.000000 ft drum the two requirements sit at 23.270539 ft and 2.396801 ft. What does a gap that wide tell a designer?', '["The vessel is entirely a liquid-holding problem, so effort spent on the gas side of the sizing will not move the length at all.", "The vessel is close to changing hands between its two requirements, so a small move in the level or in the duty could put the gas in control.", "The gas requirement was taken on the wrong area, since two requirements are expected to land within a foot of each other.", "The drum is oversized for its gas and should be narrowed to 5.000000 ft."]'::jsonb, 0, 'A vessel whose two numbers sit close together is a different animal. Here the liquid controls every row, from 59.572579 ft at 5.000000 ft of bore to 14.893145 ft at 10.000000 ft.'),
  ('separation', 'intermediate', 'module', 'm02-two-lengths-one-vessel', 15, 'ABANA-1 holds 35.091146 ft3 of retention volume and ABANA-2 holds 584.852431 ft3. What separates those two figures?', '["They are one duty read at two levels, since a retention volume falls away with the level fraction the drum is run at.", "They are one vessel before and after the retention time in its specification was doubled.", "They belong to different vessels on one field: a vertical test separator holding 3000.000000 bpd for 3.000000 minutes, and a horizontal production separator carrying 24000.000000 bpd of oil with 6000.000000 bpd of water.", "They are a liquid volume and a gas volume for the same stream."]'::jsonb, 2, 'A retention volume is a rate times a time and both are inputs. The two vessels share a field and never share a figure.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 1, 'ABANA-2 puts 29.490437 ft3/s through 25.132741 ft2 at a level of 0.500000, which is 1.173387 ft/s. Where does that numerator come from?', '["The 110.000000 MMscfd stream taken to 614.700000 psia, 95.000000 degF and a z of 0.908065, which is the volume the drum passes each second.", "The 110.000000 MMscfd stream at standard conditions, which is 1273.148148 standard ft3/s and is the volume a separator running at 614.700000 psia has to move.", "The gas density of 2.239712 lb/ft3 multiplied by the gas area, which turns a mass rate into the volume the gas space is asked to carry.", "The settling velocity of 1.958255 ft/s times the gas area of 25.132741 ft2."]'::jsonb, 0, 'The vessel sees 29.490437 ft3/s and nothing else. Dividing 1273.148148 standard ft3/s by an area gives a velocity tens of times too high.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 2, 'The same 29.490437 ft3/s runs at 3.003871 ft/s in the 5.000000 ft drum and at 0.750968 ft/s in the 10.000000 ft drum. What does that say to somebody choosing a bore?', '["Each extra foot of bore is worth the same fall in velocity, which is why the family is published at one foot steps from 5.000000 ft up to 10.000000 ft.", "The rate must have been recomputed for each bore, since one stream cannot give four times the area a quarter of the speed.", "Widening a narrow drum buys a great deal of gas room and widening a wide one buys very little, because the area climbs with the square of the bore.", "The level was raised on the wider drums to keep the margin comfortable."]'::jsonb, 2, 'From 5.000000 ft to 6.000000 ft the velocity falls from 3.003871 ft/s to 2.086022 ft/s. From 9.000000 ft to 10.000000 ft the same foot is worth 0.927121 ft/s down to 0.750968 ft/s.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 3, 'A margin of 1.668891 is reported beside ABANA-2. Which division produced it?', '["The gas velocity divided by the settling velocity, so any figure above one says the gas is winning and liquid is leaving with it.", "The settling velocity of 1.958255 ft/s divided by the gas velocity of 1.173387 ft/s, so the gas in the gas space moves more slowly than a droplet falls through it.", "The gas area of 25.132741 ft2 as a share of the whole cross-section of 50.265482 ft2.", "The gas length of 2.396801 ft as a share of the gas height of 4.000000 ft."]'::jsonb, 1, 'A margin above one says a droplet falls faster than the gas carries it along. Below one the gas is winning and liquid that should be landing leaves with it.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 4, 'The 6.000000 ft drum returns a length of 41.369847 ft, a slenderness of 6.894974 and gasCapacityOk false. What can be built from that row?', '["Nothing at all, because the engine withholds the dimensions of a vessel that fails its capacity check and prints the reasons in their place.", "A vessel whose verdict is advisory, since gasCapacityOk is a remark beside the dimensions rather than a field the sweep acts on.", "A vessel for a smaller stream, since the length of 41.369847 ft belongs to the liquid duty alone.", "A fully dimensioned vessel that will not separate what the specification asked."]'::jsonb, 3, 'A fabricator could build 41.369847 ft at a bore of 6.000000 ft from that row and every figure on it is arithmetically correct. The margin of 0.938751 is what says it will not do the job.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 5, 'The verdict turns from false to true between the 6.000000 ft and the 7.000000 ft rows, at margins of 0.938751 and 1.277745. Why is that boundary worth printing?', '["It marks the bore at which the liquid requirement stops controlling the length, which on this family is where the two requirements cross each other.", "It fixes the smallest bore the stream can be given, since the engine will not report rows below the bore at which a verdict turns true.", "It shows a reviewer what anybody arguing for a smaller vessel is arguing against, which a sweep of the passing rows alone would hide.", "It shows where the margin passes one, which is the only row a sweep keeps."]'::jsonb, 2, 'The repaired sweep returns every row with its reasons, so the failures stay beside the successes. The family crosses the threshold between 6.000000 ft and 7.000000 ft of bore.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 6, 'A summary sheet rounds the 6.000000 ft drum''s margin of 0.938751 to the nearest whole number. What has it reported?', '["A margin of one on a drum whose verdict is false, because the rounded figure and the threshold are the same number.", "The margin the engine would return at a level of 0.300000, since rounding a ratio has the same effect as moving the level that produced it.", "Nothing that matters, since the verdict of false travels beside the margin and cannot be rounded away.", "The 7.000000 ft drum''s margin in the place of the 6.000000 ft drum''s."]'::jsonb, 0, 'The 6.000000 ft drum reports gasCapacityOk false at 0.938751. A reader handed the verdict alone cannot tell 1.277745 from 2.607642 either, so the pair travels together.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 7, 'The settling velocity of 1.958255 ft/s on ABANA-2 is built from which inputs?', '["The gas velocity of 1.173387 ft/s and the margin of 1.668891, which are the two figures the capacity check holds against each other.", "The gas area of 25.132741 ft2 and the gas height of 4.000000 ft at a level of 0.500000.", "The droplet diameter the vessel is specified to take out of the gas.", "A horizontal mesh K of 0.400000 with a liquid of 55.919504 lb/ft3 and a gas of 2.239712 lb/ft3, so an operating pressure change moves the density and the velocity together."]'::jsonb, 3, 'K, the two densities and therefore the pressure all move it, so a margin is not a fixed property of a vessel. The K of 0.400000 is itself a derated table value.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 8, 'Why can the gas length never exceed the gas height on a vessel that passes its capacity check?', '["Because the capacity check compares the gas length against the gas height directly and returns gasCapacityOk false whenever the first of them is the larger.", "The gas length is the velocity ratio times the gas height, and passing holds that ratio at one or below.", "Because a droplet that has crossed the gas height has reached the liquid, so the engine caps the reported requirement at the height it crossed.", "Because the gas height at a level of 0.500000 is half the diameter, and no requirement may exceed half a bore."]'::jsonb, 1, 'On the 8.000000 ft drum the gas height is 4.000000 ft and the gas length is 2.396801 ft. The overloaded published case breaks the bound at 16.976527 ft against 3.000000 ft.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 9, 'Under this method, when can the gas requirement take control of a horizontal vessel''s length?', '["When the vessel is gas overloaded and has already failed the check, or when it is so wide for its duty that the liquid asks for less than its own gas height.", "Whenever the settling velocity falls under the gas velocity of 1.173387 ft/s, which happens on any drum whose mist extractor was specified for a vertical vessel instead.", "Whenever the level is raised above 0.500000, since a higher level shortens the gas height and lengthens the ride a droplet has to take.", "On any row where the two requirements sit within a foot of each other."]'::jsonb, 0, 'The published overloaded case is the first of those, at a margin of 0.176715 with gasCapacityOk false and a gas length of 16.976527 ft. On a passing vessel with a real liquid duty the gas cannot win.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 10, 'The bound on the gas length is pinned by a gate on the engine. What has to be said about it alongside?', '["It rests on the capacity rule and the length requirement being taken at the same level, and the engine applies that rule at a level of 0.500000 while the length follows whatever level was typed into the sheet.", "It holds only for the six bores this family publishes, since the ratio was checked on those rows alone and a bore between two of them has never been put through the same gate.", "It rests on Souders-Brown being borrowed as the droplet settling velocity, which is HELD FOR LITERATURE, so it is a property of this method rather than a fact about separators.", "It applies to a vertical vessel too, where the gas height is the whole height."]'::jsonb, 2, 'If the literature sizes a gas length from a stated droplet diameter, the ratio stops being the same quantity as the capacity check and the bound has to be read again from scratch.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 11, 'The 5.000000 ft drum reports a margin of 0.651911 and the 10.000000 ft drum reports 2.607642. How should each be read?', '["Both sit inside the ordinary spread of a family, since a margin is a ratio and any positive value describes a vessel that works.", "The first is marginal and could be recovered by rounding, and the second is the row a sweep will prefer.", "The first fails on slenderness and the second fails on gas capacity.", "The first is a long way outside the check rather than a marginal case, and the second says the gas has more than twice the room it needs, which is a reason to ask what the extra steel bought."]'::jsonb, 3, 'The 5.000000 ft row carries gas-capacity and ld-out-of-band together. A margin of 2.607642 is a comfortable vessel and an expensive one.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 12, 'The 5.000000 ft row carries the reasons gas-capacity and ld-out-of-band. What different responses do those two ask for?', '["Both ask for a wider bore, since the slenderness of 11.914516 and the margin of 0.651911 are two readings of one shortage of cross-section on that row.", "The band can be restated by the project, and a capacity failure has to be designed out.", "The capacity failure can be waived by a reviewer with the authority, and the slenderness has to go back to the vendor for a different shell.", "Neither asks for anything, since a reason is a note attached to a row the sweep has already set aside."]'::jsonb, 1, 'A slenderness outside the band is a preference somebody expressed. gasCapacityOk false at a margin of 0.651911 is the vessel failing to do the job it exists for.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 13, 'The gas holds 25.132741 ft2 at a level of 0.500000 and 37.582708 ft2 at 0.300000 on the 8.000000 ft drum. What does that do to the capacity reading?', '["The velocity falls and the settling velocity falls with it, since both are taken in the gas space, so the margin holds where it was.", "The margin holds, because the capacity check is taken at the level the vessel was sized at rather than the level it is run at.", "The velocity falls from 1.173387 ft/s to 0.784681 ft/s, so the margin improves although nothing about the stream has changed.", "The verdict turns false, because a lower level shortens the fall a droplet makes."]'::jsonb, 2, 'Gas velocity is the actual rate over the gas area. More area at the same 29.490437 ft3/s is slower gas and a larger margin, while the liquid side is losing the area it needs.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 14, 'What goes missing when a report quotes gasCapacityOk true without the margin, or the margin without the verdict?', '["The verdict on its own cannot tell 1.277745 from 2.607642, and the margin on its own leaves a reader to remember where the threshold sits.", "The reasons list goes with them, which is the only place a row records whether its slenderness was inside the band of 3.000000 to 5.000000.", "The level the reading was taken at, which the engine prints beside the verdict.", "The gas area the velocity was divided by."]'::jsonb, 0, 'The two answer different questions: whether the vessel carries its gas, and by how much. A margin of 0.938751 rounds to a pass and a bare true hides 2.607642.'),
  ('separation', 'intermediate', 'module', 'm03-gas-capacity', 15, 'Why does the repaired sweep report the rows that fail rather than dropping them?', '["The failing rows are needed to compute the preferred row, which is taken across the family once the reasons have been weighted against each other.", "A reader can see what was rejected and why, so the boundary between 6.000000 ft and 7.000000 ft stays visible and nobody has to guess whether the smallest offered bore was ever considered.", "A row that fails on gas may still pass on slenderness, and a sweep reports one reading at a time.", "The engine cannot tell a failing row from a passing one until a band is supplied."]'::jsonb, 1, 'A sweep that printed only the vessels that worked would hide the boundary. Every row carries its own reasons, so 41.369847 ft at 6.000000 ft of bore is visible as a failure.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 1, 'Where does the 350.000000 bbl slug on ABANA come from, and what happens when it is missing?', '["It is computed from the normal rate of 12000.000000 bpd across the hold of 5.000000 minutes, and a missing figure is replaced by that product so that the sizing can go on.", "It is recovered from the working volume of 391.666667 bbl by taking the normal inflow back off it, and a missing figure throws a SeparatorInputError naming the input.", "It is typed in from the pigging tab of the line sizing studio, and without it the engine returns { error: \"a slug volume is needed (the line sizing studio computes it)\" }.", "It is an output of the catcher sizing, and a missing figure is reported as a slug of nothing."]'::jsonb, 2, 'The message names the studio that owns the number. A reader is told where to go rather than left to invent a figure that will then be sized to six decimals.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 2, 'ABANA takes a 350.000000 bbl slug with 12000.000000 bpd still arriving over a 5.000000 minute hold. What is the vessel sized on?', '["391.666667 bbl of working volume, the slug plus the 41.666667 bbl that arrives while the catcher is draining.", "350.000000 bbl, with the 41.666667 bbl of normal inflow held back as the margin that the fill fraction of 0.600000 provides.", "391.666667 bbl of vessel volume, which the fill fraction has already been applied to.", "The 3665.075231 ft3 the slug occupies at 12000.000000 bpd."]'::jsonb, 0, 'The plant keeps producing while the catcher drains, so both volumes have to fit. The fill fraction of 0.600000 then turns 391.666667 bbl into 3665.075231 ft3.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 3, 'Why is ABANA''s vessel volume 3665.075231 ft3 rather than the working volume carried straight into cubic feet?', '["The conversion also has to carry the normal inflow of 41.666667 bbl, which is quoted in barrels and has to be added in cubic feet.", "A vessel cannot be filled to the top with liquid, so the fill fraction of 0.600000 stands between 391.666667 bbl of working volume and the drum that has to contain it.", "A slug catcher is sized at its slenderness of 4.000000 first, and the volume follows from the two dimensions.", "The engine rounds the working volume up to the nearest vendor drum."]'::jsonb, 1, 'Treating 391.666667 bbl as the vessel volume specifies a drum with no vapour space at all. The fill fraction is an input in the same way the hold time is.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 4, 'Why can 3665.075231 ft3 on its own not describe a drum?', '["Because a cylinder''s volume depends on the fill fraction of 0.600000 as well, and the fill has to be applied before either dimension can be recovered from it.", "Because the engine sizes a catcher from the slug of 350.000000 bbl and uses the volume only to check the answer afterwards.", "Because a volume in cubic feet has to be taken back into barrels before a diameter can be found.", "A volume fixes only the product of the bore and the length, so a second statement is needed."]'::jsonb, 3, 'The slenderness of 4.000000 splits it into 10.527155 ft of diameter and 42.108619 ft of length. That ratio is an input the project chose.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 5, 'A sweep prints several catchers one under another and one row reads 13.984106 ft beside 69.920531 ft. How does a reader check that the pair belongs together?', '["The length is the diameter times the ratio, and 13.984106 ft at a slenderness of 5.000000 gives 69.920531 ft.", "The slug of 1200.000000 bbl over the fill of 0.700000 gives the length directly, so a row whose length disagrees has been mixed with another run.", "The normal inflow of 138.888889 bbl moves with the diameter, so the two are reconciled through the hold time of 10.000000 minutes.", "The pair cannot be checked, since the ratio is an output of the sizing."]'::jsonb, 0, 'The relationship between the two dimensions is the input that was typed. A diameter of 8.650995 ft at a ratio of 4.000000 gives 34.603982 ft the same way.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 6, 'The published 1200.000000 bbl case holds its slug for 10.000000 minutes at 20000.000000 bpd and adds 138.888889 bbl, while ABANA adds 41.666667 bbl. What drives that difference?', '["The fill fraction of 0.700000 against 0.600000, which decides how much of the drum is left for liquid arriving after the slug.", "The slug of 1200.000000 bbl, since the normal inflow is taken as a share of the slug.", "A longer hold on a higher rate, since the normal inflow is the rate carried across the hold time and both inputs push it up.", "The slenderness of 5.000000 against 4.000000."]'::jsonb, 2, '41.666667 bbl is 12000.000000 bpd across 5.000000 minutes. A long hold on a high-rate line makes the normal inflow a serious part of the vessel.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 7, 'ABANA''s harp needs 2456.380208 ft3 against the drum''s 3665.075231 ft3. What accounts for that gap?', '["Fingers of 20.000000 inch bore hold liquid more densely than a drum does, so the same working volume of 391.666667 bbl occupies less space in pipe.", "The harp was sized at a shorter hold, which takes the normal inflow out of its working volume.", "The drum figure includes its heads and the harp figure does not.", "The fill fraction of 0.800000 against 0.600000, and the finger form sizing on the 350.000000 bbl slug alone while the vessel form carries the 41.666667 bbl of normal inflow too."]'::jsonb, 3, 'The two forms answer slightly different questions from the same inputs. A reader comparing them on volume is comparing an answer with the hold in it against one without.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 8, 'ABANA''s harp is 5.000000 fingers of 20.000000 inch bore filled to 0.800000. What does the engine return?', '["2456.380208 ft3 in all, 1125.921751 ft in each finger, and 225.184350 ft2 of cross-section once the five bores have been added together.", "2456.380208 ft3 in all, 225.184350 ft in each finger over 2.181662 ft2, and 1125.921751 ft of pipe.", "3665.075231 ft3 in all, since a working volume is the same whichever form the catcher takes, spread over 2.181662 ft2 in each finger.", "391.666667 bbl in all, carried at the fill fraction of 0.800000 into 225.184350 ft of pipe altogether."]'::jsonb, 1, 'Each 20.000000 inch finger offers 2.181662 ft2. Five of them share 2456.380208 ft3 at 225.184350 ft each, and the pipe to buy and support comes to 1125.921751 ft.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 9, 'The published 500.000000 bbl harp has longer fingers than the 1500.000000 bbl one, at 670.191518 ft against 558.492932 ft. How does the smaller slug ask for more length?', '["Four fingers of 16.000000 inch bore is far less cross-section than six of 24.000000 inch, so a third of the slug still needs more length in each finger.", "The 500.000000 bbl case is filled to 0.750000 against 0.800000, and a lower fill is what stretches its fingers past the larger harp''s 558.492932 ft, the fill dividing a volume before any bore is applied.", "The larger harp spreads 10527.343750 ft3 over six fingers, and a volume that large is always shorter per finger whatever bore it is given.", "The smaller harp counts the normal inflow and the larger one does not."]'::jsonb, 0, 'Bore and count are the two choices in a harp. 3743.055556 ft3 across four 16.000000 inch fingers is 670.191518 ft each.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 10, 'Squeezing ABANA''s slug into 2.000000 fingers of 12.000000 inch bore gives 1563.780209 ft in each. What does the engine do with that?', '["It refuses on nFingers, since a harp of that length cannot be built and the engine declines to return a dimension nobody could fabricate out of pipe on a real plot.", "It holds each finger at about 1500 ft and adds a third finger to carry the remainder, which keeps the harp inside the length the warning describes without moving the bore.", "It returns the dimensions with a warning that fingers longer than about 1500 ft each call for more fingers or a larger bore rather than a very long harp.", "It returns the dimensions with no comment, since buildability sits outside its scope."]'::jsonb, 2, 'The warning is advice about buildability rather than a refusal, and the fix it names is more fingers or a wider bore.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 11, 'A request for 2.5 fingers is refused as "nFingers must be a whole number of at least 1 (got 2.5)". Why refuse it rather than round it?', '["Rounding would move the volume in each finger, and the engine rounds only inputs that leave the total volume of the harp where it was.", "A harp is built from whole pipes, so 2.5 is a typing slip or an arithmetic result that was never meant to reach the form, and rounding would answer a request nobody made.", "A count under 3.000000 fingers sits outside the range the harp relation was fitted over.", "The engine rounds only fractions above one half."]'::jsonb, 1, 'The message quotes the value back, which turns a complaint into an instruction: a reader who sees 2.5 knows at once whether they typed it or something upstream produced it.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 12, 'Which inputs on the slug catcher tab accept a value of zero?', '["The slenderness and the hold time, since a flat vessel and an instant drain are both real requests, while a normal rate of zero would leave the working volume undefined.", "The fill fraction and the hold time, since a drum filled to nothing is simply an empty drum and the engine sizes it anyway.", "None of them, because every input on this tab is guarded as a positive number and quoted back when it fails.", "The hold time and the normal liquid rate, while a slenderness of zero and a finger count below one are refused."]'::jsonb, 3, 'A hold time of zero says the vessel drains as fast as the slug arrives. A slenderness of zero is not a squat vessel, and neither it nor a fractional finger describes anything buildable.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 13, 'A negative hold time and a fill fraction outside its range are both rejected on this tab. How do the two rejections differ?', '["The hold time is caught by the studio form before the engine sees it, and the fill fraction is caught by the engine once the working volume has been worked out.", "Both of them throw, and the difference is that the hold time message quotes the value back while the fill fraction message names the acceptable range.", "The hold time throws a SeparatorInputError naming holdMin, and the fill fraction comes back as { error: \"the fill fraction must be between 0 and 1\" }.", "The hold time is refused and the fill fraction is held at 0.600000."]'::jsonb, 2, 'A throw says the request was malformed and names the input. A returned error describes a state the method has no answer for. Neither is a number to carry forward.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 14, 'What is wrong with quoting ABANA''s catcher as a 42.108619 ft vessel?', '["It leaves out the 10.527155 ft of bore that goes with it, so a plot plan drawn from the length alone inherits whatever ratio the next reader assumes.", "It leaves out the working volume of 391.666667 bbl, which is the only figure on which two catchers may be compared at all once their slenderness ratios differ.", "It quotes the harp''s length rather than the drum''s, which is 225.184350 ft in each finger.", "It uses a length the engine reports only at a fill fraction of 0.600000."]'::jsonb, 0, 'The two dimensions come as a pair from one volume and one ratio. 13.984106 ft at a ratio of 5.000000 is a different animal from 10.527155 ft at 4.000000.'),
  ('separation', 'intermediate', 'module', 'm04-slug-catchers', 15, 'A study sets the drum''s 3665.075231 ft3 against the harp''s 2456.380208 ft3 and calls the harp the smaller catcher. What has that comparison missed?', '["That a harp is quoted in pipe rather than in shell, so the 1125.921751 ft of pipe has to be converted before the two can be set against each other.", "The two volumes answer different questions, since the harp was sized on the slug alone at a fill of 0.800000 while the drum carries the normal inflow at a fill of 0.600000.", "That the drum figure is a working volume in barrels and the harp figure is a vessel volume in cubic feet.", "Nothing, since both were sized from the same 350.000000 bbl slug."]'::jsonb, 1, 'The gap is part fill fraction and part the 41.666667 bbl of normal inflow that the finger form never counted.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 1, 'On the ERHA plot the flare carries a table requirement of 90.000000 m and a computed radiation setback of 64.6458 m. What separates those two figures?', '["The table figure covers a flare against a control room and the setback covers a flare against a tank, so the two belong to different pairs on the plan.", "The table figure already carries the allowable of 4.730000 kW/m2 inside it, and the setback re-derives the same requirement from the duty as a check on it.", "Both are computed, and the difference between them is the transmissivity.", "The table figure is a recorded value that stays where it is, and the setback moves with the relief rate and the allowable it was solved for."]'::jsonb, 3, 'The flare releases 828000.0000 kW, and a change in the duty moves 64.6458 m. Nothing a flare does moves 90.000000 m.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 2, 'What may a course say about the spacing figure of 90.000000 m?', '["That it is the API 521 requirement for a control room at an allowable of 1.580000 kW/m2, which is why a flare is held further off from a control room than from a tank at 60.000000 m.", "That it is a customary figure this engine records with no source checked, waiting to be replaced by a site standard, so no conclusion may be built on the number itself.", "That it came out of the same point source model that gives 64.6458 m, at a stricter allowable.", "That it is the distance below which a layout fails whatever the duty."]'::jsonb, 1, 'The table figures and the API 521 labels are both HELD FOR LITERATURE. A course may teach what a table is and how a lookup behaves.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 3, 'The lookup returns 0.000000 m for a separator against its own dump valve and null for a tank against a skid. What is the difference between those two answers?', '["A zero is a pair the check passes and a null is a pair it fails, since an unknown requirement is treated as the strictest figure the table carries anywhere on the plan.", "A zero comes out of the table and a null comes from two items sharing a set of coordinates.", "A zero is a requirement of nothing that the check counts on its own, and a null means the table carries no figure for that pair at all, so nothing was judged.", "There is none: both are read as no requirement."]'::jsonb, 2, 'On ERHA 21 pairs carry no requirement against 69 comparisons that do. Reading a null as a zero counts a pair that was never checked as a pair that passed.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 4, 'What does a separator against a tank return, and what does a tank against a separator return?', '["15.000000 m both ways, because the lookup is symmetric.", "15.000000 m in the first direction and 30.000000 m in the second, since the table is written from the item with the larger inventory towards the smaller one.", "15.000000 m in the first direction and null in the second, since a pair is recorded once and the reverse order has to be entered separately.", "It depends on which of the two carries a radiation source, because a computed setback replaces the table figure."]'::jsonb, 0, 'A pair the table does not carry comes back as null rather than a guess, and that holds in either direction.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 5, 'Why does the engine measure the ERHA plot on a sphere rather than on a flat grid?', '["The datum at 4.741200 north and 7.183600 east is quoted in degrees and the engine carries no projection, so it works on the sphere those coordinates were written on and accepts whatever error follows from that.", "Degrees of longitude shrink as the latitude rises, so a plan that reads a difference in degrees as a fixed number of metres is wrong by an amount that depends on where the site sits.", "A spacing table is written edge to edge while a plan measures centre to centre, and only a spherical measurement can carry the correction for the size of each item on the plot.", "The published cases were solved with Vincenty, and a flat grid would disagree with them at 1111.9508 m."]'::jsonb, 1, 'The engine uses the haversine formula. Over a few hundred metres the choice between a sphere and an ellipsoid does not matter and the choice between a sphere and a grid does.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 6, 'The published distance cases agree to the figure printed across haversine, Vincenty and the straight chord, including 55.5975 m at high latitude. What does that agreement show?', '["That the three are one formula written three different ways, so the published cases are checking the coordinate handling rather than any of the geometry behind it.", "That a flat grid would agree with them as well, since every method converges below 1111.9508 m and the equator case is the longest distance published.", "That the engine checks its distances against an ellipsoid while it runs.", "At the scale of a plot plan the earth model makes no difference to the answer, which is what lets one spherical formula serve the whole site."]'::jsonb, 3, 'Vincenty solves on an ellipsoid and the chord cuts straight through the earth. Agreement at 89.4099 m and at 489.2584 m is what makes a sphere defensible here.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 7, 'Every distance on the plot runs from one item''s icon to another''s. What does that leave out when a requirement is written edge to edge?', '["Half of each item, which is negligible on a small one and is 9.0000 m on a tank inside an 18.000000 m bund, and the omission always makes the plot look more generous than it is.", "Nothing, since a table figure such as 15.000000 m is written centre to centre for exactly this reason.", "The bund itself, which is not on the plan and carries no coordinates.", "Half of the larger item only, the smaller one being inside the tolerance."]'::jsonb, 0, 'It is not a rounding error and it always points the same way. The pool fire result reports a radius from the centre and a setback from the edge for that reason.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 8, 'The ERHA flare relieves 18.000000 kg/s of gas at 46000.000000 kJ/kg. What is the first figure in the chain, and what is done to it?', '["The radiated fraction of 0.300000 applied to the mass rate first, which gives the part of the 18.000000 kg/s burning as radiation before the heat of combustion is applied to it.", "The allowable of 4.730000 kW/m2 times the area of a sphere at the table distance of 90.000000 m, which is the power the setback is then solved against.", "828000.0000 kW of heat release, of which 0.300000 is radiated and then spread over a sphere down to the allowable.", "The flame height, which the Thomas correlation gives before any radiation is worked out."]'::jsonb, 2, 'Mass rate times heat of combustion gives 828000.0000 kW. A fraction of that is radiated, and the point source model asks where the intensity falls to 4.730000 kW/m2.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 9, 'The published flare at 920000.0000 kW is checked by reading the intensity back at its own setback of 68.1427 m. What does that check establish?', '["That the point source model has been validated against a measured flare, since a reading of 4.7300 kW/m2 could only come from an instrument standing at that distance.", "That the transmissivity of 1.000000 on that case is right, since any loss in the air would leave the intensity under the allowable at 68.1427 m.", "That 68.1427 m is conservative, the intensity there being under the allowable.", "That the distance solves to the allowable it was given, since the intensity there reads 4.7300 kW/m2."]'::jsonb, 3, 'The arithmetic is checked by walking it backwards. The published cases are synthetic, so agreement is a check on the arithmetic rather than on the physics.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 10, 'The 215000.0000 kW published flare needs 49.3602 m while the 920000.0000 kW one needs 68.1427 m. Why is the smaller duty not a proportionally smaller distance?', '["Radiation spreads over a sphere, so distance follows the square root of the power, and the smaller case also carries a stricter allowable of 1.580000 kW/m2 with a transmissivity of 0.900000.", "The smaller case radiates 0.250000 of its heat against 0.300000, and a setback is proportional to the radiated fraction rather than to the heat release behind it.", "The setback is bounded below by the flame height, which is what holds 49.3602 m up.", "The smaller flare was solved from a different datum."]'::jsonb, 0, 'The inputs differ in three places: the duty, the allowable and the transmissivity. None of the three moves a setback in proportion.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 11, 'The ERHA bund is 18.000000 m across. What does the engine work out from that, and in what order?', '["A flame height of 23.7996 m first, then the heat release of 601819.1967 kW that implies, then the pool area of 254.4690 m2 the flame is standing on.", "A radius of 59.5294 m out of the table, then the heat release that radius implies at 4.730000 kW/m2.", "A pool area of 254.4690 m2, a mass burning rate of 13.9958 kg/s at 0.055000 kg/m2/s, a heat release of 601819.1967 kW, a flame of 23.7996 m by Thomas, and a radius of 59.5294 m.", "A setback of 50.5294 m, then the radius standing 9.0000 m outside it."]'::jsonb, 2, 'Each step is arithmetic on the step before it, and every one of them is driven by the size of the bund.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 12, 'The pool result reports a radius of 59.5294 m and a setback of 50.5294 m. Which figure does a centre-to-centre layout check need?', '["The setback of 50.5294 m, because a setback is the distance a neighbouring item has to stand at while the radius is an intermediate figure inside the calculation.", "The radius of 59.5294 m, because the tank icon sits at the centre of its bund.", "Either of them, since the two differ by 9.0000 m and the check applies its own tolerance to a radiation comparison.", "The setback of 50.5294 m, with the half bund of 9.0000 m added to the measured distance instead of to the requirement."]'::jsonb, 1, 'Passing the edge figure into a centre-to-centre check leaves every comparison short by half the bund. That is the defect that failed open.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 13, 'A pool fire run at an allowable of 4000.000000 kW/m2 returns a radius of 2.2745 m, an edge setback of 0.0000 m and setbackStatus within-pool-edge. What is the engine saying?', '["The radius lies inside the pool edge at 10.0000 m from the centre and well inside the flame height of 25.6078 m, so the answer is a lower bound rather than a distance to build to.", "The calculation failed and the zero is a placeholder, which is why a status is attached in the place of a distance somebody could act on.", "The pool is too small to radiate at that allowable, so the setback is reported as zero and the reader is expected to fall back on the spacing table for the pair.", "A neighbouring item may stand against the bund wall, the setback from the edge being 0.0000 m."]'::jsonb, 0, 'The engine reports 0.0000 m rather than a negative distance and says why. It instructs a designer to use a solid-flame view factor model for design.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 14, 'What does the pool fire model leave out?', '["The flame height, which is why the Thomas correlation has to be run as a separate step before a radius such as 59.5294 m can be reported for a bund at all.", "The atmospheric transmissivity, which has to be applied to the reported radius by hand once an allowable has been chosen for the target.", "A view factor and a solid-flame surface emissive power, which is why it under-predicts close to the fire where the flame is not small.", "The burning rate of 0.055000 kg/m2/s."]'::jsonb, 2, 'It spreads the radiated fraction over a sphere, which is a good approximation at a distance. Inside the flame height it under-predicts, and the status says so.'),
  ('separation', 'intermediate', 'module', 'm05-distances-on-a-site', 15, 'The flare stands 46.1777 m from the control room, against a table figure of 90.000000 m and a computed setback of 64.6458 m. What has the plot been told?', '["One finding recorded twice, since the radiation setback is the calculation that lies behind the table figure and the shorter of the two is the one that governs the plot.", "Two separate findings: the spacing breaks a convention somebody recorded, and this flare at this duty puts more than 4.730000 kW/m2 on that building.", "That the table figure is superseded, a computed setback being the requirement wherever both exist.", "That the plot passes on radiation and fails on spacing."]'::jsonb, 1, 'The pair fails both. A table cannot know a relief rate, so a flare well inside a 90.000000 m rule can still exceed its allowable.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The ERHA station reports 69 comparisons carrying a positive requirement and 21 pairs carrying none. What puts a pair in one group rather than the other?', '["A pair counts when both items are placed and the distance between them is under the requirement, so the 21 are the pairs that cleared the figure they were held against.", "A pair counts as a check when the table gives it a positive requirement, and a table figure of 0.000000 m is counted on its own instead.", "A pair counts when its requirement came out of the table, and the 21 are pairs whose requirement was computed from a flare duty or a bund instead.", "A pair counts when the two items share a type, and the 21 are the mixed pairs."]'::jsonb, 1, 'Valve and relief-valve pairs score 0.000000 m in this table. They are reported separately so that a clean sheet cannot be built out of pairs nobody judged.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'worstAbsolute names the flare against the control room at 43.8223 m short, and worstRelative names one transfer pump against the other at 0.597753 of its requirement. Why does the engine report both?', '["The absolute ranking covers spacing breaches and the relative one covers radiation breaches, so between them they carry the two kinds of requirement on the plan.", "The relative ranking is the one the engine calls worst, and the absolute figure is printed beside it for scale.", "Both name the same pair on most plots, and ERHA happens to be the exception.", "They answer different questions and they name different pairs, so a reviewer who reads one ranking has read half the plot."]'::jsonb, 3, 'A pump 1.7933 m short of 3.0000 m is the sharpest breach in proportion. A control room 43.8223 m short of 90.0000 m is the largest in metres.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Transfer pump A stands 1.2067 m from Transfer pump B against a requirement of 3.000000 m. Why does that pair matter more than it looks?', '["It is the sharpest breach on the plot in proportion, at 0.597753 of its requirement, and a gap of 1.7933 m is the sort of finding a reader scanning for large numbers walks straight past.", "It is the largest breach in metres on the plot, which is why the nearest-neighbour listing puts it above the flare and the control room.", "It is the only pair on the plot for which the table carries no figure, so the shortfall cannot be scored at all.", "It is a pair of one type, and the table doubles the requirement for those."]'::jsonb, 0, 'The nearest-neighbour reading is how a reviewer comes across it. The flare to the control room is 43.8223 m short and is the worst in metres.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'The ERHA check reports 2 skipped items. What were they?', '["Two pairs whose requirement came back as null from the table, which the check sets aside because no figure exists to hold a distance against.", "Two comparisons that failed the table and the computed setback together, which are reported once rather than twice in the violation list.", "A tank with bad coordinates and a radiation source that was never placed on the plan.", "Two items whose type the table does not carry, which is the same count as the unknown type pairs."]'::jsonb, 2, 'They are recorded as tk2 with bad-coordinates and fl2 with radiation-source-not-placed. Skipped items are part of why complete is false on this plot.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The station reports 12 unknown type pairs, all of them from one chemical injection skid. What does that do to the reading?', '["The 12 join the 21 pairs with no requirement, since a null and a zero both describe a comparison the table declined to score.", "The layout cannot be called complete, because a pair the table has no row for was never judged against anything.", "The check treats them as passing, because an item the table does not carry can impose no distance on anything around it.", "The skid is dropped and the remaining items are checked again."]'::jsonb, 1, 'The production manifold''s nearest neighbour is that skid at 5.8533 m, against a requirement of null. A table with no row for modern equipment leaves a real plot incomplete.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'ABANA-2 at 8.000000 ft reports a liquid requirement of 23.270539 ft, a gas requirement of 2.396801 ft and a margin of 1.668891. What is the full reading?', '["A vessel 23.270539 ft long, controlled by the liquid, carrying its gas with room to spare at a slenderness of 2.908817 outside the band.", "A vessel 23.270539 ft long whose gas requirement of 2.396801 ft has been satisfied by that length, which is what the margin of 1.668891 records.", "A vessel 2.396801 ft long, the gas being the binding requirement at that margin.", "A vessel that fails on slenderness and is therefore not reported."]'::jsonb, 0, 'Three answers travel together: the length, the requirement that set it, and whether the vessel carries its gas. A band of 3.000000 to 5.000000 is a separate preference.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'A Professional answer sheet quotes a pressure, a gas rate and a site distance. Which conventions does it follow?', '["A gauge and an absolute pressure may stand in for each other, the standard rate is the one to quote, and site work is in feet as the vessel is.", "Pressures are quoted in psia throughout, rates in MMscfd, and distances in metres to six decimals.", "Vessel work is in metres and site work in feet.", "600.000000 psig is written 614.700000 psia where it is absolute, the vessel sees 29.490437 ft3/s rather than 1273.148148 standard ft3/s, and site distances are metres to four decimals."]'::jsonb, 3, 'Vessel figures print to six decimals while metres, kilowatts and seconds print to four. Nothing on a plot plan is quoted in feet.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'In the Professional reading, what does the slug catcher on ABANA come to?', '["350.000000 bbl of working volume, a drum 10.527155 ft by 42.108619 ft, and a harp carrying that same volume once a fill fraction of 0.600000 has been applied to its fingers.", "391.666667 bbl of working volume and a drum 42.108619 ft across, the slenderness of 4.000000 having been taken on the length rather than on the bore.", "391.666667 bbl of working volume, a drum 10.527155 ft by 42.108619 ft, or a harp of 225.184350 ft in each finger.", "3665.075231 bbl of working volume, which a fill fraction turns into a drum of 10.527155 ft."]'::jsonb, 2, 'The slug of 350.000000 bbl plus 41.666667 bbl of normal inflow makes the working volume. The harp is sized on the slug alone, at 1125.921751 ft of pipe.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Of the figures 90.000000 m, 64.6458 m and 59.5294 m on the ERHA reading, which is a table figure and which are calculations?', '["90.000000 m is the table, while 64.6458 m comes from 828000.0000 kW and 59.5294 m from an 18.000000 m bund.", "All three are calculations, since the table figures were themselves solved at the allowable levels API 521 records for a control room and for a tank.", "90.000000 m and 64.6458 m are table figures for a flare, and only the pool radius of 59.5294 m is computed from a duty.", "All three are table figures, which is why they are held for the literature."]'::jsonb, 0, 'A computed setback moves when the duty moves. The flare setback follows the relief rate and the pool radius follows the size of the bund.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Four gaps turn up in a Professional exercise: a level of 1, a missing slug volume, a table pair with no entry, and a pool answer inside the flame height. What do they share?', '["Each of them is a state the engine recovers from by supplying its own default, so a reader has to find out which default was applied before quoting the result.", "Each of them is an answer in itself, and writing a plausible figure into any of them turns a correct reading into a wrong one.", "Each of them is a thrown SeparatorInputError naming the input it came from.", "Each of them is reported as a zero for the reader to interpret."]'::jsonb, 1, 'A level of 1 is refused by name, a missing slug volume returns an error naming the studio that owns it, a table pair returns null, and a pool result carries setbackStatus within-pool-edge.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Why does this tier insist that a vessel figure is quoted to six decimals and a site figure to four?', '["Because the goldens are recorded at those precisions and a figure quoted any other way is refused by the studio form before it can reach a marking sheet at all.", "Because vessel work is in feet and site work in metres, and a metre carries fewer significant figures.", "Because rounding on the way to an answer changes the answer: a margin of 0.938751 rounds to one, and one is a pass on a vessel whose verdict is false.", "Because a capstone is marked to the digit."]'::jsonb, 2, 'Six decimals on a vessel and four on a site are the precisions the two halves of this engine print. A figure rounded on the way to an answer is a different answer, and a reader cannot tell which they were handed.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A sheet quotes a liquid requirement of 23.270539 ft for the 8.000000 ft drum on ABANA-2, with the duty named and the requirement labelled. Which condition is still missing?', '["The slenderness of 2.908817, which is the only figure saying whether a length belongs to a vessel that can be built and transported.", "The controlling requirement, because a length with no label beside it could as easily have been the gas requirement of 2.396801 ft.", "The retention volume of 584.852431 ft3, without which the length cannot be checked against the area at all.", "The level of 0.500000, since the same drum on the same duty asks for 46.113917 ft at 0.300000."]'::jsonb, 3, 'Neither length is wrong and only one was asked for. A length is meaningless without the level it was sized at.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Before the repair, a layout that had checked nothing came back with a pass. Why is that reading dangerous on a plot like ERHA?', '["A pass computed from nothing still carries worstAbsolute and worstRelative, so a reviewer sees two rankings naming pairs that were never compared.", "A clean sheet could then come from a plan where the table had no row for most of its pairs, which is what 12 unknown type pairs and 2 skipped items would produce.", "A plan with 21 pairs carrying no requirement would report those as failures instead, which is the opposite error and every bit as misleading.", "It would move the six breaches out of the violation list."]'::jsonb, 1, 'ERHA reports 69 checks and still comes back incomplete. A verdict has to say how much was judged before a pass means anything.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'The inlet separator''s nearest neighbour is its own dump valve at 2.8348 m against a requirement of 0.000000 m, and the production manifold''s is a skid at 5.8533 m against null. Which of those is a finding?', '["Neither is a breach, and the null is the one worth noting, because a pair with no table row leaves the layout incomplete.", "Both are findings, since a distance under 3.000000 m between any two items is the shortest spacing the table carries anywhere on the plot.", "The dump valve at 2.8348 m, because a requirement of 0.000000 m means no separation was ever agreed.", "The skid, because 5.8533 m is under 15.000000 m."]'::jsonb, 0, 'A requirement of 0.000000 m is a pair the table scores at nothing. A requirement of null is a pair it cannot score at all, and 12 of those sit on this plan.'),
  ('separation', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'This tier treats the liquid in a horizontal drum as one phase. What does the tier after it add, and what does that change about the chord?', '["A second liquid whose surface is the chord itself, which is why a chord is reported at every level of the cross-section table.", "A droplet specification, which turns the chord into the height a drop has to cross.", "A second liquid with its own surface inside the liquid area, placed at its own height by the retention times, which is a different surface from the gas-liquid chord of 8.000000 ft at half full.", "A wider slenderness band, which moves the chord with it."]'::jsonb, 2, 'Reading the chord as the height of a water layer is the error the retired app made. The chord is a width across the drum and an interface is a height inside the liquid.'),
  ('separation', 'intermediate', 'final', null, 1, 'An operator drops the level on the 8.000000 ft drum from 0.500000 to 0.300000 and asks whether the vessel still fits its duty. What moves?', '["Both requirements rise together, since the level decides how much of the 50.265482 ft2 each phase is given and neither side gains from a lower liquid level.", "The liquid requirement holds at 23.270539 ft because the retention volume of 584.852431 ft3 has not moved, and only the gas reading changes.", "The liquid area falls to 12.682775 ft2 and the requirement rises to 46.113917 ft, while the gas gets 37.582708 ft2 and slows to 0.784681 ft/s, so liquid controls by a wider gap than before.", "The gas requirement takes control, because a lower level leaves the gas 5.600000 ft of height to cross."]'::jsonb, 2, 'One cut divides the circle. The liquid loses area and needs 46.113917 ft, and the gas gains area and slows down, so the gap between the two requirements widens.'),
  ('separation', 'intermediate', 'final', null, 2, 'Drop ABANA-2 from a level of 0.500000 to 0.300000 and the gas velocity falls from 1.173387 ft/s to 0.784681 ft/s while the vessel lengthens from 23.270539 ft to 46.113917 ft. What did that one move do?', '["The same 29.490437 ft3/s crossed a gas area grown to 37.582708 ft2, and the same retention volume spread over a liquid area shrunk to 12.682775 ft2.", "The rate was taken again at the lower level, since a level setting changes the conditions the stream is read at and 29.490437 ft3/s belongs to 0.500000.", "The settling velocity of 1.958255 ft/s was re-derived at the new level, which moved the velocity, and the margin of 2.495607 forced the longer drum.", "Only the liquid moved. 0.784681 ft/s is the velocity along the liquid space and the gas above it still crosses 25.132741 ft2."]'::jsonb, 0, 'One move with two consequences, and they point opposite ways. The gas requirement falls from 2.396801 ft to 2.243943 ft while the liquid requirement doubles.'),
  ('separation', 'intermediate', 'final', null, 3, 'The retention volume of 584.852431 ft3 is the same on every row of the ABANA-2 family. What does that fix about the liquid requirement column?', '["Nothing, since the volume is taken again on each row from that row''s liquid area and the retention time of 3.000000 minutes.", "Every row of it is that one volume over that row''s liquid area: 25.132741 ft2 gives 23.270539 ft and 39.269908 ft2 gives 14.893145 ft.", "That the column falls in proportion to the bore, so 59.572579 ft at 5.000000 ft and 14.893145 ft at 10.000000 ft stand in the ratio of their diameters.", "That the column is flat and what moves across the family is the gas requirement."]'::jsonb, 1, 'A volume over an area is a length. The duty fixes the volume and the bore and the level fix the area, so the column is one division repeated six times.'),
  ('separation', 'intermediate', 'final', null, 4, 'ABANA-2 at 6.000000 ft runs its gas at 2.086022 ft/s against a settling velocity of 1.958255 ft/s. How much more bore does the family say that vessel needs?', '["None at all, since a margin of 0.938751 is within a twentieth of one and the row is reported with gasCapacityOk true.", "Two feet, because the row has to clear the band of 3.000000 to 5.000000 as well, and the 7.000000 ft row sits at a slenderness of 4.342025.", "Four feet, because the gas area has to double before the velocity falls under the settling figure and 39.269908 ft2 is the first row that gives it.", "One foot. The 7.000000 ft row runs 1.532587 ft/s at a margin of 1.277745."]'::jsonb, 3, 'The 6.000000 ft row is the last one the gas overruns. At 7.000000 ft the gas area is 19.242255 ft2 and the verdict turns true.'),
  ('separation', 'intermediate', 'final', null, 5, 'gasOverloaded6ftGasControls runs its gas at 2.829421 ft/s against a settling velocity of 0.500000 ft/s and asks for 16.976527 ft where the gas height is 3.000000 ft. A designer has to cure it. What works?', '["A longer drum, since 16.976527 ft is the requirement the engine returned on that row and building a vessel to a stated requirement is what satisfies the check.", "A lower liquid level, because the gas space shrinks as the liquid falls and a smaller gas area is what raises a margin of 0.176715.", "More bore, because the length is long only while the velocity ratio is above one, and building the drum longer leaves that ratio exactly where it stands.", "A smaller K on the mist extractor, because 0.500000 ft/s is the figure the gas is measured against and lowering it opens the margin."]'::jsonb, 2, 'The gas length is the velocity ratio carried onto the gas height, and at a margin of 0.176715 that ratio is far above one. Bore is what moves a velocity.'),
  ('separation', 'intermediate', 'final', null, 6, 'Four figures sit on one separation sheet: a slug of 350.000000 bbl, a spacing requirement of 90.000000 m, a flare setback of 64.6458 m and a catcher volume of 3665.075231 ft3. Which of them does this engine produce?', '["The catcher volume alone, since a setback of 64.6458 m is read off the API 521 levels in the same way a spacing requirement of 90.000000 m is read off the spacing table.", "The setback and the catcher volume, while the slug arrives from the line sizing studio and the spacing requirement is read out of a table.", "The slug and the catcher volume, both being vessel quantities, while every figure quoted in metres belongs to the layout side and is looked up rather than worked out.", "All four, which is why each is quoted to the precision the engine prints."]'::jsonb, 1, 'A missing slug returns an error naming the studio that owns it. The setback moves with a heat release of 828000.0000 kW and the table figure moves with nothing at all.'),
  ('separation', 'intermediate', 'final', null, 7, 'Two distances sit on the ERHA plan for the flare: a requirement of 90.000000 m and a setback of 64.6458 m. A reviewer doubles the relief rate. Which figure moves?', '["The setback, because it is solved from a heat release of 828000.0000 kW against an allowable of 4.730000 kW/m2, while the table figure is a recorded value that knows nothing about a duty.", "Both of them, since the table row for a flare against a control room is indexed on the relief rate the flare was designed for.", "The table figure, because a spacing requirement is written for the largest duty a flare of that class carries.", "Neither, because a setback is solved once at design and held."]'::jsonb, 0, 'A computed setback moves with the duty. The table figure is HELD FOR LITERATURE, recorded with no source checked and waiting for a site standard.'),
  ('separation', 'intermediate', 'final', null, 8, 'A single sheet carries a slug catcher and a plot plan. Which units belong where?', '["Barrels for the catcher and feet for the plot, since both are dimensions of plant and the vessel convention governs the whole sheet from end to end.", "Cubic feet for the catcher volume and kilowatts per square metre for every distance on the plot, radiation being the reason the distances exist.", "Metres throughout, since a plot plan and a vessel are drawn on the same drawing and a single unit avoids a conversion.", "Barrels and cubic feet with feet for the catcher, and metres for the plot."]'::jsonb, 3, '391.666667 bbl becomes 3665.075231 ft3 and then 10.527155 ft by 42.108619 ft. Site work is in metres to four decimals, and nothing on a plot plan is quoted in feet.'),
  ('separation', 'intermediate', 'final', null, 9, 'A chord of 8.000000 ft across a drum and a distance of 43.1555 m across a plot are both measured between two points. What does each convention leave out?', '["The chord leaves out the length of the drum and the site distance leaves out the elevation, which is why each of them is quoted alongside a second figure on every row of a listing.", "The chord says nothing about where the liquid stands, since two levels share one width, and a centre-to-centre distance leaves out half of each item it runs between.", "The chord leaves out the gas height above it, and the site distance leaves out the bund the tank stands inside, which the engine adds back as 9.0000 m.", "Neither leaves anything out, since both are measured between fixed points."]'::jsonb, 1, 'Levels of 0.400000 and 0.600000 share a chord of 7.838367 ft. A tank inside an 18.000000 m bund carries 9.0000 m of the centre-to-centre difference on its own.'),
  ('separation', 'intermediate', 'final', null, 10, 'On the judged station the heater treater sits 50.1598 m from the crude tank and is reported 9.3696 m short, the smallest of the four radiation breaches on the plot. What does that particular breach illustrate?', '["The two rankings disagreeing, since 9.3696 m is the smallest shortfall in metres anywhere on this plot while 0.157395 of the requirement is the largest shortfall on it as a fraction of what was asked for.", "A pair that belongs against the spacing table instead, a heater treater against a tank carrying a figure of 30.000000 m.", "Nearly all of it is the half bund: measured against the edge figure of 50.5294 m that distance would read as barely short, and against the radius of 59.5294 m it is 9.3696 m short.", "A rounding difference, 9.3696 m and the half bund of 9.0000 m being one distance."]'::jsonb, 2, 'The radius is measured from the pool centre and the setback from the pool edge, and the gap between them is 9.0000 m. The shortfall is 0.157395 of the requirement.'),
  ('separation', 'intermediate', 'final', null, 11, 'The ERHA layout returns two rankings. What would be lost by quoting only the one with the larger number of metres on it?', '["The flare against the control room at 43.8223 m, which is the breach a reviewer is most likely to be asked about and the one the relative ranking hides.", "Every radiation breach, since the absolute ranking is built from spacing comparisons and the relative one from the computed setbacks.", "The count of comparisons that carried a positive requirement, which travels with the relative ranking alone.", "The pump pair at 0.597753 of its requirement, which is the sharpest breach in proportion."]'::jsonb, 3, 'worstAbsolute names the flare and the control room at 43.8223 m short. worstRelative names Transfer pump A against Transfer pump B at 0.597753. They are different pairs.'),
  ('separation', 'intermediate', 'final', null, 12, 'A status pack prints a margin of 0.9 for one drum of the ABANA-2 family and gives no bore beside it. Which row is it, and what does the print cost the reader?', '["The 6.000000 ft row at 0.938751, and what is lost is the verdict: it is the one row in the family whose margin sits near enough to one to be mistaken for a pass.", "The 7.000000 ft row at 0.927121, and nothing is lost, since every reading below one carries gasCapacityOk false whatever the bore turns out to be.", "The 5.000000 ft row at 0.651911, and what is lost is the size of the shortfall rather than the verdict.", "No row at all: every margin this family reports is under 0.651911 or over 1.277745, so a figure of 0.9 has come from another run."]'::jsonb, 0, 'The family runs 0.651911, 0.938751, 1.277745, 1.668891, 2.112190 and 2.607642. Only one of those is close enough to one for the verdict to be the thing a reader needs.'),
  ('separation', 'intermediate', 'final', null, 13, 'A studio catches the SeparatorInputError for a liquid level of 0 and carries on at 0.500000. What has it produced?', '["A correct answer reached by the shortest route, since 0.500000 is the level the six teaching rows are centred on and the drum was always going to be sized there.", "A fully dimensioned vessel for a level nobody typed, which is a refusal turned into an assumption.", "An error object naming the input, since a caught throw is re-raised as a returned state once the sizing has been attempted at the substituted level.", "Nothing at all, because the engine refuses the whole sizing call once any input has failed."]'::jsonb, 1, 'No default, clamp or fallback stands in for a refused input. The message names liquidLevelFrac and quotes the value back so the reader can see what was typed.'),
  ('separation', 'intermediate', 'final', null, 14, 'A spreadsheet computes 2.5 fingers for a harp and hands that to the engine. What comes back, and what is the reader meant to do?', '["A harp of 3.000000 fingers, since the engine rounds a finger count up to the next whole pipe and records that it did so in the returned object.", "A harp of 2.000000 fingers with a warning about the length of each one, which on ABANA''s slug would come out at 1563.780209 ft.", "A refusal on nFingers quoting 2.5 back, which tells the reader at once whether they typed it or something upstream produced it.", "An error object saying the fill fraction must be between 0 and 1."]'::jsonb, 2, 'A harp is built from whole pipes. Rounding a count silently would answer a request nobody made, so the engine names the input and stops.'),
  ('separation', 'intermediate', 'final', null, 15, 'A layout summary counts every pair the table scored at 0.000000 m and every pair it returned null for as pairs that passed. What has that summary claimed?', '["That 21 pairs with no requirement and 12 pairs the table has no row for were all judged and cleared, when none of them was ever compared against a figure.", "That the table is symmetric, which it is, so a pair recorded once counts in both directions and the total of 69 comparisons is doubled.", "That the skipped items were checked, which the engine records separately as tk2 and fl2.", "That a zero requirement is stricter than a null one."]'::jsonb, 0, 'A zero is a requirement of nothing and a null is no figure at all. Counting either as a pass builds a clean sheet out of pairs nobody judged.'),
  ('separation', 'intermediate', 'final', null, 16, 'A vessel is judged against a slenderness band of 3.000000 to 5.000000 and a slug catcher is sized at a slenderness of 4.000000. What is the difference between those two uses of a ratio?', '["The band is computed from the two length requirements while the catcher''s ratio is read from the fill fraction, so one is an output and the other is a property of the liquid.", "The band applies to horizontal vessels and the catcher''s ratio to vertical ones, which is why the two are quoted against different bounds.", "There is none, since both are preferences about fabrication and transport that a project may restate at will.", "The band judges a shape the duty produced, and the catcher''s ratio is the input that splits a volume into a bore and a length."]'::jsonb, 3, 'ABANA-2 reads 2.908817 because its duty and bore produced it. ABANA''s catcher is 10.527155 ft by 42.108619 ft because 4.000000 was typed in.'),
  ('separation', 'intermediate', 'final', null, 17, 'A sweep prints six fully dimensioned rows and a reader picks the 6.000000 ft drum at 41.369847 ft because it suits the plot plan. What has been overlooked?', '["That row carries the reason ld-out-of-band at a slenderness of 6.894974, which is a fabrication preference the project is free to restate in writing.", "That row reports gasCapacityOk false at a margin of 0.938751, so the vessel is arithmetically correct and will not do its job.", "That row was computed at a level of 0.300000 while the rest of the family was computed at 0.500000.", "That row belongs to ABANA-1 rather than to ABANA-2."]'::jsonb, 1, 'Nothing in a length of 41.369847 ft warns anybody. Two of the six rows describe vessels that cannot carry their gas.'),
  ('separation', 'intermediate', 'final', null, 18, 'The published 6.000000 ft horizontal case reports a gas velocity of 0.707355 ft/s and a gas requirement of 2.496548 ft, while the published 8.000000 ft case at a level of 0.400000 reports 0.952689 ft/s and 4.157188 ft. What is the pair showing?', '["Three times the gas rate bought less than twice the gas length, because the wider drum at a lower level gave the gas more area to cross and the two effects sit inside one product.", "That a gas requirement rises with the level, since 0.400000 leaves more of the circle to the gas and lengthens the ride a droplet takes.", "That the gas requirement is proportional to the gas rate, which is why 30.000000 ft3/s gives roughly three times the length of 10.000000 ft3/s.", "That both vessels are gas controlled, at 2.496548 ft and 4.157188 ft."]'::jsonb, 0, 'Both published cases are controlled by their liquid, at 20.684923 ft and 31.149488 ft. The gas requirement moves very little for a large change in rate.'),
  ('separation', 'intermediate', 'final', null, 19, 'An area of 49.202836 ft2 is taken back to a depth on a 10.000000 ft drum, and an area larger than that drum''s circle is asked for as well. What comes back in each case?', '["6.000000 ft for the first, and a SeparatorInputError naming the area input for the second, since an area outside the circle is a malformed request.", "An approximation near 6.000000 ft for the first, the bisection being cut off after 100 steps, and a clamp at the full circle for the second.", "6.000000 ft for the first, and { error: \"the area must lie between zero and the full circle\" } for the second.", "A refusal for both, since a depth is an input to a segment and never an output of one."]'::jsonb, 2, 'The two directions are exact inverses and the bisection resolves the depth to double precision. An impossible area is a state the method has no answer for, so it is returned rather than thrown.'),
  ('separation', 'intermediate', 'final', null, 20, 'The published distance cases are solved three ways and agree to the figure printed, from 55.5975 m up to 1111.9508 m. What does a reader take from that?', '["That the haversine formula has been validated against surveyed ground, since three independent methods landing on 89.4099 m could only agree if the distance had been measured.", "That Vincenty and the chord are approximations of the haversine result, which is why the engine publishes the haversine figure as the answer for every pair.", "That distances under 1111.9508 m need no earth model at all and may be taken from the difference in degrees.", "At plot scale the earth model does not matter, and the choice between a sphere and a flat grid does."]'::jsonb, 3, 'Vincenty solves on an ellipsoid and the chord cuts straight through the earth. Degrees of longitude shrink with latitude, which is what a flat grid gets wrong.'),
  ('separation', 'intermediate', 'final', null, 21, 'The ERHA station reports 69 comparisons, 21 pairs with no requirement, 12 unknown type pairs and 2 skipped items. Which of those four counts explain an incomplete reading?', '["The pairs with no requirement and the unknown type pairs, since a table figure of 0.000000 m and a null are both the table declining to score a pair on the plan.", "The unknown type pairs and the skipped items, because both are comparisons the check could not make at all.", "The 69 comparisons, since a plot with that many pairs cannot be judged fully within one run of the check.", "The skipped items alone, an unknown type pair being scored at the strictest figure available."]'::jsonb, 1, 'A skid the table has no row for gives 12 unknown pairs, and tk2 and fl2 were skipped for bad coordinates and for a radiation source that was not placed.'),
  ('separation', 'intermediate', 'final', null, 22, 'A sizing sheet carries a liquid level fraction of 0.500000 and a fill fraction of 0.600000. What does each one do?', '["The level cuts the drum''s circle into 25.132741 ft2 of liquid and 25.132741 ft2 of gas, and the fill turns 391.666667 bbl of working volume into a catcher of 3665.075231 ft3.", "The level fixes how much of the catcher may be filled with liquid, and the fill fraction fixes how much of the separator''s circle the liquid occupies.", "Both are operating settings a controller holds, one on the separator and one on the catcher.", "The level is an input and the fill fraction is an output of the catcher sizing."]'::jsonb, 0, 'They belong to different vessels and different questions. A level of 0 or 1 is refused by name, and a fill fraction outside its range comes back as a returned error.'),
  ('separation', 'intermediate', 'final', null, 23, 'The operating pressure on ABANA-2 moves. Which figures on its row travel with it, and which hold still?', '["Only the gas density of 2.239712 lb/ft3 travels, because the actual rate follows the standard rate of 1273.148148 standard ft3/s, which is fixed at the sales meter and carries the vessel reading with it.", "Only the settling velocity of 1.958255 ft/s travels, since K is derated on pressure while the two densities are properties of the fluids.", "Nothing travels, the vessel having been sized at 614.700000 psia.", "The gas density of 2.239712 lb/ft3, the actual rate of 29.490437 ft3/s and the settling velocity of 1.958255 ft/s all travel, while the areas the level of 0.500000 cuts hold still."]'::jsonb, 3, 'Souders-Brown reads K with both densities, so the margin of 1.668891 is not a fixed property of a vessel. The liquid area of 25.132741 ft2 belongs to the bore and the level.'),
  ('separation', 'intermediate', 'final', null, 24, 'finger1500bbl6x24in holds 10527.343750 ft3 and finger500bbl4x16in holds 3743.055556 ft3. Which figures on those two cases are the ones a project actually buys?', '["The pipe totals, 3350.957591 ft and 2680.766073 ft, because a harp is bought and supported as pipe and the volumes are what that pipe contains.", "The volumes, since a catcher is specified by the liquid it has to hold and 10527.343750 ft3 against 3743.055556 ft3 is the whole of the comparison.", "The per finger lengths, 558.492932 ft and 670.191518 ft, because the shorter finger is the cheaper harp whatever the count of them.", "Neither, because both cases were sized on a slug alone and no harp can be costed until a normal inflow has been added to it."]'::jsonb, 0, 'The finger form sizes on the slug alone. 1500.000000 bbl at a fill of 0.800000 needs 3350.957591 ft of pipe, and 500.000000 bbl at 0.750000 needs 2680.766073 ft in a longer finger of smaller bore.'),
  ('separation', 'intermediate', 'final', null, 25, 'One reviewer halves the relief rate on the ERHA flare and another drops ABANA-2 from a level of 0.500000 to 0.300000. What moves in each case?', '["Both the setback of 64.6458 m and the table figure of 90.000000 m move, a spacing requirement being indexed on the duty of the flare it was written for, and on the vessel only the liquid requirement moves with the level.", "The setback of 64.6458 m moves while the table figure of 90.000000 m does not, and on the vessel the areas, the requirement and the velocity all move while the 50.265482 ft2 of shell stays put.", "Neither figure on the site moves, a layout being judged once, while on the vessel every figure on the row moves with the level.", "The table figure moves and the setback holds, and on the vessel the shell falls to 37.582708 ft2."]'::jsonb, 1, 'A computed setback follows its duty and a table figure follows nothing. The liquid requirement goes from 23.270539 ft to 46.113917 ft in a drum that has not changed.'),
  ('separation', 'intermediate', 'final', null, 26, 'A plan reports complete false with 2 skipped items. One reviewer says the plot has failed and another says nothing has been proved. Who is right?', '["The first, since an item the engine could not place is a defect in the plan and the check records it as a violation with the others.", "The first, because a layout that cannot be completed is reported with pass false and the two readings always move together on a real plot.", "The second: complete says how much of the plan was judged, and a skipped item is a comparison that was never made.", "Neither, because the count of skipped items is advisory and does not enter the reading."]'::jsonb, 2, 'ERHA reports complete false and pass false, and they are separate findings. tk2 has bad coordinates and fl2 is a radiation source that was not placed.'),
  ('separation', 'intermediate', 'final', null, 27, 'A sheet carries three requirements for one plot: a band of 3.000000 to 5.000000, a spacing figure of 15.000000 m and a pool radius of 59.5294 m. What kind of number is each?', '["A typed preference about fabrication, a recorded table value with no source checked, and a calculation that moves with the size of the bund it came from.", "Three calculations, since each of them is returned by an engine and carries the precision the engine prints it at.", "Two calculations and one preference, the spacing figure being solved from the allowable levels API 521 records.", "Three preferences, since all of them can be restated by a project."]'::jsonb, 0, 'Moving the band moves which rows carry ld-out-of-band and changes no dimension. A site standard replaces the table wholesale. The radius follows an 18.000000 m bund.'),
  ('separation', 'intermediate', 'final', null, 28, 'On the 8.000000 ft drum at a level of 0.200000 the gas height and the gas-liquid chord are both 6.400000 ft. What should a reader make of that?', '["That the chord equals the gas height wherever the level sits below half, which is what the table shows at 0.300000 with a chord of 7.332121 ft.", "That the section is square at that level, so the gas space can be read as 6.400000 ft by 6.400000 ft and its area taken as the product of the two.", "That 0.200000 is where the chord reaches its largest, since a chord widens as the liquid falls and the table stops there.", "A coincidence of that one row. The two are a height and a width, and they part company on every other level the table prints."]'::jsonb, 3, 'At a level of 0.500000 the chord is the full 8.000000 ft and the gas height is 4.000000 ft. Two equal figures on one row of a table are not a relationship.'),
  ('separation', 'intermediate', 'final', null, 29, 'The ABANA-2 family reports liquid controlling on all six rows, with gas requirements from 3.834882 ft down to 1.917441 ft. If the borrowed settling velocity moved, how much of that table would be read again?', '["The whole table, because the liquid lengths from 59.572579 ft down to 14.893145 ft are divisions by an area the same velocity fixed.", "None of it, because liquid controls every row and a requirement that never wins cannot change a length.", "The gas column and the controlling column, since a gas requirement computed another way could win a row, and the liquid column stands.", "The slenderness column alone, since L/D is computed from a length and the lengths are what a moved packaging touches."]'::jsonb, 2, 'It is held for the literature, so the packaging is a property of this method. A liquid requirement is a retention volume over a liquid area and reads no settling velocity at all.'),
  ('separation', 'intermediate', 'final', null, 30, 'The engine carries four radiation levels with labels, from 1.580000 kW/m2 for continuous exposure up to 9.460000 kW/m2 for an escape route. What is their status?', '["They are the levels the point source model was fitted against, which is why a setback solved at 4.730000 kW/m2 can be checked by reading the intensity back at that distance.", "They are the API 521 customary levels as this engine records them, with the labels held for the literature and no source checked.", "They are inputs a site standard supplies, so the engine carries none of its own and refuses a setback until an allowable is typed.", "They are outputs of the pool fire model at four standard pool sizes."]'::jsonb, 1, 'The arithmetic that turns an allowable into a distance is the engine''s own and is checked against the published cases. Choosing which level applies to a building is a judgement the labels only describe.'),
  ('separation', 'intermediate', 'final', null, 31, 'A catcher is quoted as 3665.075231 ft3 with no other figure beside it. What can a fabricator do with that?', '["Nothing yet, because a volume fixes only the product of the bore and the length, and the slenderness of 4.000000 is what gives 10.527155 ft by 42.108619 ft.", "Build the drum, since a volume and the fill fraction of 0.600000 between them fix both dimensions of a cylinder.", "Build the drum at the published slenderness, which every catcher in this module carries.", "Convert it back to 391.666667 bbl and order to that."]'::jsonb, 0, 'One statement more is needed before there is a vessel. The published 1200.000000 bbl case at a ratio of 5.000000 gives 13.984106 ft by 69.920531 ft from 10739.004630 ft3.'),
  ('separation', 'intermediate', 'final', null, 32, 'gasCapacityOk on a vessel and setbackStatus on a pool fire are both returned beside numbers. What does each add to the figure it travels with?', '["Both are advisory notes for a reviewer, since the dimensions and the distances are complete answers on their own and neither of the two flags enters a calculation anywhere.", "The verdict grades the margin against one, and the status grades the setback against the table figure for that pair.", "The verdict says the vessel does or does not carry its gas, and the status says whether the point source model is being read in the region it is good for.", "Both record whether an input was missing when the answer was produced."]'::jsonb, 2, 'A margin of 0.938751 comes with false. A radius of 2.2745 m comes with within-pool-edge, which says the answer is a lower bound rather than a distance to build to.'),
  ('separation', 'intermediate', 'final', null, 33, 'A project has to choose between two rows of one family, one inside a band of 3.000000 to 5.000000 at 4.342025 and one below the band at 2.908817. On what grounds is that choice made?', '["The 7.000000 ft drum, because a row inside the band is the only row a sweep treats as feasible and the 8.000000 ft row is rejected with its reasons attached.", "The 8.000000 ft drum, because a lower slenderness is a shorter vessel at 23.270539 ft and a shorter vessel is cheaper to fabricate and transport.", "The 7.000000 ft drum, because a margin of 1.277745 is closer to the threshold and therefore the more efficient use of steel.", "The question is not settled by the band, since both carry their gas and one of them simply sits outside a typed preference."]'::jsonb, 3, 'Both report gasCapacityOk true, at margins of 1.277745 and 1.668891. Band membership is a preference and feasibility is a verdict, and they are reported separately.'),
  ('separation', 'intermediate', 'final', null, 34, 'The nearest neighbour of the heater treater is the separator relief valve at 19.4836 m, against a table requirement of 0.000000 m. What should a reviewer do with that row?', '["Treat it as the weakest pair on the plot, since a requirement of 0.000000 m means the table has no view and the distance has to be justified some other way.", "Read it and move on, because a requirement of nothing is a pair the check counts on its own rather than a pair that passed.", "Raise it as a breach, since the heater treater against a tank is 30.000000 m in the same table and the relief valve inherits that figure.", "Add it to the 12 unknown type pairs, which is where a zero requirement is counted."]'::jsonb, 1, 'Two rows of this table read 0.000000 m. On ERHA 21 pairs carry no requirement, and they are reported apart from the 69 comparisons that do.'),
  ('separation', 'intermediate', 'final', null, 35, 'A velocity is taken by dividing 29.490437 ft3/s by 50.265482 ft2, on the grounds that the figure sits on every row of the cut while the gas share runs from 43.108759 ft2 down to 9.826958 ft2. What is wrong with that?', '["The gas area is the total less a vapour allowance, and the allowance grows as the level rises, which is why the gas keeps less of the circle at 0.750000.", "The total is the area used for the capacity check and the gas area is used for the gas length, which is why both are carried on every row of the table.", "The shell never changes and the level moves only the split, so a gas velocity taken on the total is a velocity taken on an area the gas does not have.", "The gas area is the figure a droplet falls across and the total is the figure it travels along."]'::jsonb, 2, 'At a level of 0.750000 the gas holds 9.826958 ft2 of that same circle. Dividing 29.490437 ft3/s by 50.265482 ft2 says the vessel has room it does not have.'),
  ('separation', 'intermediate', 'final', null, 36, 'A sheet quotes ABANA''s catcher, 391.666667 bbl of working volume at a fill of 0.600000 and a slenderness of 4.000000, as 10.527155 ft across and 34.603982 ft long. Which dimension came from another run?', '["The length. That bore at a ratio of 4.000000 gives 42.108619 ft, and 34.603982 ft belongs to the published 200.000000 bbl catcher at a bore of 8.650995 ft.", "The bore, since a length of 34.603982 ft at a ratio of 4.000000 asks for 8.650995 ft, which is the catcher the smaller published slug produced.", "Neither, since a catcher is sized from its volume and both figures sit comfortably with 3665.075231 ft3 once the fill of 0.600000 has been applied.", "Both, since 391.666667 bbl at a fill of 0.600000 comes to 3665.075231 ft3 and neither quoted dimension belongs to a drum of that volume."]'::jsonb, 0, 'The two dimensions of a catcher are one volume split by one typed ratio, so they either agree or one has been carried over. 3665.075231 ft3 at 4.000000 is 10.527155 ft by 42.108619 ft.'),
  ('separation', 'intermediate', 'final', null, 37, 'Two pool fire answers reach a reviewer, the ERHA bund at beyond-pool-edge and a published case at within-pool-edge. What does that pair of statuses settle?', '["Whether the pool was measured from its centre or from its edge, which is the 9.0000 m the layout check has to carry on the ERHA bund itself.", "Whether the allowable behind each was taken from the API 521 levels or typed by the project, which is what separates a defensible answer from an absurd one.", "Whether the flame height was found by Thomas, a status of within-pool-edge being what the engine returns when that correlation is skipped.", "Whether each answer may be used as a distance or only as a lower bound."]'::jsonb, 3, 'beyond-pool-edge confirms that 50.5294 m sits where a point source is defensible. within-pool-edge says a radius of 2.2745 m is inside the flame height of 25.6078 m and under-predicts.'),
  ('separation', 'intermediate', 'final', null, 38, 'A report quotes a liquid requirement of 46.113917 ft for ABANA-2 and a reviewer who remembers 23.270539 ft calls it an error. Who is right?', '["The reviewer, because 23.270539 ft is the requirement at the level this drum was sized at and any other figure belongs to a different vessel entirely.", "Both figures are right and they belong to different levels, 0.300000 and 0.500000, so the report is wrong only if it left the level out.", "The report, because 46.113917 ft is the requirement once the retention volume of 584.852431 ft3 has been corrected for the gas space above it.", "Neither, since a liquid requirement cannot be quoted without the gas requirement beside it."]'::jsonb, 1, 'The same drum and the same duty give both. A length is meaningless without the level it was sized at, which is why the level belongs in the record.'),
  ('separation', 'intermediate', 'final', null, 39, 'Going from 8.000000 ft to 9.000000 ft on ABANA-2 shortens the vessel from 23.270539 ft to 18.386599 ft. What else does that foot buy, and what does it cost?', '["It costs margin, since the wider drum passes the same rate at 0.927121 ft/s against the 1.173387 ft/s of the narrower one.", "It buys a smaller liquid area, since 31.808626 ft2 holds the same retention volume in a shorter drum than 25.132741 ft2 does.", "It buys margin, 1.668891 up to 2.112190, and it costs shape, 2.908817 down to 2.042955 and further below the band.", "It buys and costs nothing measurable, because both rows already carry gasCapacityOk true and both already sit outside the band of 3.000000 to 5.000000."]'::jsonb, 2, 'Every extra foot on this family shortens the drum, raises the margin and lowers the slenderness at the same time. The two rows differ in degree on all three.'),
  ('separation', 'intermediate', 'final', null, 40, 'Three answers arrive with something attached to them: a harp whose fingers reach 1563.780209 ft, a pool radius of 2.2745 m, and a lookup for a tank against a skid. What came with each?', '["A warning about buildability with the dimensions still returned, a status saying the distance is only a lower bound, and a null, which is the table saying it holds no figure for that pair at all.", "A refusal naming nFingers, a setback of 0.0000 m with nothing attached to it, and a requirement of 0.000000 m for a pair the table scores at nothing.", "Three warnings, the engine attaching advice wherever an answer lands outside the range its method was built for.", "A warning, a refusal and a zero."]'::jsonb, 0, 'The harp keeps its dimensions and gains advice, the pool keeps a distance and gains setbackStatus, and the lookup returns nothing rather than a guess.'),
  ('separation', 'intermediate', 'final', null, 41, 'What single reading tells a reviewer that the ERHA flare is a problem for the control room on two separate grounds?', '["43.8223 m of shortfall, which the engine reports once as worstAbsolute and once as an entry in the violation list, so the same breach appears twice on one reading.", "46.1777 m standing against a table figure of 90.000000 m and a computed setback of 64.6458 m, which are a convention and a radiation intensity.", "0.285681 of the requirement, which is the radiation shortfall expressed as a fraction and covers the spacing breach as well.", "The 12 unknown type pairs, which include the control room."]'::jsonb, 1, 'A table cannot know a relief rate, so the two findings are separate. The radiation shortfall on that pair is 18.4681 m and the spacing shortfall is 43.8223 m.'),
  ('separation', 'intermediate', 'final', null, 42, 'horizontal8ftAt40pctLiquidControlledInBand reports liquid 31.149488 ft, gas 4.157188 ft, length 31.149488 ft, controlling liquid, L/D 3.893686 and a gas velocity of 0.952689 ft/s. Which of the six cannot be recovered from the rest?', '["The controlling requirement, since two lengths of 31.149488 ft and 4.157188 ft standing side by side do not say which of them set the vessel.", "The slenderness of 3.893686, since a bore of 8.000000 ft and a length of 31.149488 ft do not produce it without the band being stated too.", "The gas velocity of 0.952689 ft/s, because it is the only figure on the row that says how much room the gas had, and the capacity verdict rests on it.", "The length of 31.149488 ft, since a total length is computed separately from the two requirements that were compared to arrive at it."]'::jsonb, 2, 'The length is the larger of the two requirements and the controlling field names which one, and 31.149488 ft over a bore of 8.000000 ft is the slenderness. Only the velocity carries the gas headroom.');
